/**
 ******************************************************************************
 * @file    brendon_ports.c
 * TEAM CODE (owner: Brendon - battery monitor and USB-C MSC) - written by the BJT2 team, not generated by STM32CubeMX.
 * @brief   Board-side implementations of the PD5b_Brendon Interfaces/ ports.
 *
 * Owner: Brendon Bone — Battery Monitoring & USB-C subsystem (PD6).
 *
 * RTOS role: helpers for BrendonTask (owner of I2C1 + USB device state).
 * See brendon_ports.h for the per-port context rules. Owner-task pattern
 * (lecture 07 slide 22): only BrendonTask ever calls the gauge bus below
 * (and Brendon_Init, once, before the kernel starts).
 *
 * A "port" is a small table of function pointers (Interfaces/ in
 * PD5b_Brendon): the host-tested code calls the hardware through it, so the
 * same code runs here and, with mocks, in the PC tests. In file order:
 *   1. bq_bus.h: gauge reads / writes on I2C1 (interrupt + thread flag, or
 *      the blocking fallback this .ioc, the CubeMX project file, still uses)
 *   2. charger_pins.h: four plain GPIO reads (STAT, PG, ALERT, VBUS)
 *   3. msc_sd_ops.h: the SD card for USB-MSC; the block reads / writes run
 *      inside the OTG_FS interrupt, the bring-up in BrendonTask
 *   4. BrendonPorts_Init (before the kernel): keep the I2C handle, MSC_Init
 ******************************************************************************/
#include "brendon_ports.h"
#include "app_rtos.h"
#include "main.h"
#include "sd_bsp_override.h"     /* SD_Bus4BitStatus(): stay 1-bit when D1-D3 failed the read test */

#define BQ_ADDR            (0x55U << 1)     /* 7-bit 0x55, HAL wants it shifted */
#define BQ_I2C_TIMEOUT_MS  100U
#define SD_BLOCK_TIMEOUT_MS 1000U

static I2C_HandleTypeDef *s_hi2c = NULL;
static MSC_Store          s_msc_store;
extern SD_HandleTypeDef   hsd;              /* CubeMX, main.c */

volatile uint32_t g_msc_host_writes = 0U;   /* see brendon_ports.h */

/* ============================== bq_bus.h ================================= */
/* Interrupt + thread flag, the RTOS way to wait for a peripheral:
 * HAL_I2C_Mem_Read_IT only STARTS the transfer and returns at once, then
 * BrendonTask sleeps in osThreadFlagsWait. When the transfer ends, the I2C1
 * interrupt's HAL callback (main.c) sets BRENDON_I2C_DONE_FLAG (or _ERR_FLAG)
 * on BrendonTask, which wakes it; meanwhile other tasks use the CPU. No flag
 * within 100 ms = the gauge did not answer: the I2C block is reset.
 * This .ioc has no I2C1 interrupts yet, so the blocking HAL_I2C_Mem_Read
 * (same 100 ms limit) runs instead. That is acceptable because no other task
 * uses I2C1: it only holds up BrendonTask, and the CPU time spent polling
 * comes from the lower-priority tasks (higher ones still pre-empt it). */
static uint8_t i2c_it_available(void)
{
    /* Interrupt-driven only when (a) the kernel runs so a flag wait is
     * possible, (b) we ARE BrendonTask (the flags are delivered to it), and
     * (c) CubeMX enabled both I2C1 interrupts. Otherwise blocking fallback. */
    return (osKernelGetState() == osKernelRunning &&
            osThreadGetId() == BrendonTaskHandle &&
            NVIC_GetEnableIRQ(I2C1_EV_IRQn) && NVIC_GetEnableIRQ(I2C1_ER_IRQn)) ? 1U : 0U;
}

uint8_t BrendonPorts_I2cIsInterruptDriven(void)
{
    return (NVIC_GetEnableIRQ(I2C1_EV_IRQn) && NVIC_GetEnableIRQ(I2C1_ER_IRQn)) ? 1U : 0U;
}

/* Wait for the transfer started by an _IT call: DONE flag from the
 * MemRx/MemTxCplt callback, ERR from HAL_I2C_ErrorCallback. */
static int i2c_wait_done(void)
{
    uint32_t f = osThreadFlagsWait(BRENDON_I2C_DONE_FLAG | BRENDON_I2C_ERR_FLAG,
                                   osFlagsWaitAny, BQ_I2C_TIMEOUT_MS);
    if ((f & osFlagsError) != 0U) {          /* timeout: recover the bus */
        (void)HAL_I2C_DeInit(s_hi2c);
        (void)HAL_I2C_Init(s_hi2c);
        return -1;
    }
    return (f & BRENDON_I2C_ERR_FLAG) ? -1 : 0;
}

static int bq_mem_read(void *ctx, uint8_t reg, uint8_t *data, uint16_t len)
{
    (void)ctx;
    if (i2c_it_available()) {
        (void)osThreadFlagsClear(BRENDON_I2C_DONE_FLAG | BRENDON_I2C_ERR_FLAG);
        if (HAL_I2C_Mem_Read_IT(s_hi2c, BQ_ADDR, reg, I2C_MEMADD_SIZE_8BIT, data, len) != HAL_OK) {
            return -1;
        }
        return i2c_wait_done();
    }
    /* Blocking fallback (owner-only, blocking-call audit). */
    return (HAL_I2C_Mem_Read(s_hi2c, BQ_ADDR, reg, I2C_MEMADD_SIZE_8BIT, data, len,
                             BQ_I2C_TIMEOUT_MS) == HAL_OK) ? 0 : -1;
}

static int bq_mem_write(void *ctx, uint8_t reg, const uint8_t *data, uint16_t len)
{
    (void)ctx;
    if (i2c_it_available()) {
        (void)osThreadFlagsClear(BRENDON_I2C_DONE_FLAG | BRENDON_I2C_ERR_FLAG);
        if (HAL_I2C_Mem_Write_IT(s_hi2c, BQ_ADDR, reg, I2C_MEMADD_SIZE_8BIT,
                                 (uint8_t *)data, len) != HAL_OK) {
            return -1;
        }
        return i2c_wait_done();
    }
    return (HAL_I2C_Mem_Write(s_hi2c, BQ_ADDR, reg, I2C_MEMADD_SIZE_8BIT, (uint8_t *)data, len,
                              BQ_I2C_TIMEOUT_MS) == HAL_OK) ? 0 : -1;
}

static int bq_is_ready(void *ctx)
{
    (void)ctx;
    /* 3 trials, 50 ms each — bus-level probe, blocking by nature. */
    return (HAL_I2C_IsDeviceReady(s_hi2c, BQ_ADDR, 3U, 50U) == HAL_OK) ? 0 : -1;
}

static void bq_delay_ms(void *ctx, uint32_t ms)
{
    (void)ctx;
    if (osKernelGetState() == osKernelRunning) osDelay(ms);
    else                                        HAL_Delay(ms);
}

static const BQ_Bus s_bq_bus = {
    .mem_read  = bq_mem_read,
    .mem_write = bq_mem_write,
    .is_ready  = bq_is_ready,
    .delay_ms  = bq_delay_ms,
    .ctx       = NULL,
};

void BrendonPorts_I2cDoneISR(void)
{
    if (BrendonTaskHandle != NULL) (void)osThreadFlagsSet(BrendonTaskHandle, BRENDON_I2C_DONE_FLAG);
}

void BrendonPorts_I2cErrorISR(void)
{
    if (BrendonTaskHandle != NULL) (void)osThreadFlagsSet(BrendonTaskHandle, BRENDON_I2C_ERR_FLAG);
}

/* ============================ charger_pins.h ============================= */
/* Merged_CubeMX_Spec.md: PA0 CHG_STAT, PB8 CHG_PG, PB4 GAUGE_ALERT
 * (open-drain, LOW = asserted), PA9 VBUS_SENSE. All four are plain GPIO
 * inputs set up by MX_GPIO_Init from the .ioc; the three open-drain lines
 * have internal pull-ups there, so an unconnected pin (the Nucleo test
 * setup) reads "deasserted" instead of floating into "power good" / a fake
 * fault blink. No EXTI in the .ioc, so BrendonTask polls at 100 ms (>= 10 Hz
 * keeps the 1 Hz fault blink visible).
 * STAT = the charger's status output, PG = its "power good" output (input
 * supply in range), ALERT = the gauge's alarm output; open-drain = the chip
 * can only pull the line low, the pull-up makes it high otherwise. EXTI =
 * the STM32's pin-change interrupt. What the levels mean: charger_status.c. */
static int pin_read(GPIO_TypeDef *port, uint16_t pin)
{
    return (HAL_GPIO_ReadPin(port, pin) == GPIO_PIN_SET) ? 1 : 0;
}
static int charger_read_stat(void *ctx)  { (void)ctx; return pin_read(CHG_STAT_GPIO_Port, CHG_STAT_Pin); }
static int charger_read_pg(void *ctx)    { (void)ctx; return pin_read(CHG_PG_GPIO_Port, CHG_PG_Pin); }
static int charger_read_alert(void *ctx) { (void)ctx; return pin_read(GAUGE_ALERT_GPIO_Port, GAUGE_ALERT_Pin); }
static int charger_read_vbus(void *ctx)  { (void)ctx; return pin_read(VBUS_SENSE_GPIO_Port, VBUS_SENSE_Pin); }

static const Charger_Pins s_charger_pins = {
    .read_stat  = charger_read_stat,
    .read_pg    = charger_read_pg,
    .read_alert = charger_read_alert,
    .read_vbus  = charger_read_vbus,
    .ctx        = NULL,
};

/* ============================= msc_sd_ops.h ============================== */
/* ISR-context rule: read/write/capacity/get_state are called from the
 * OTG_FS interrupt by the USB MSC class. No os* calls.
 * card_init and config_wide_bus (and get_state too) are called by MSC_Poll in
 * BrendonTask, only while the card is handed to the PC. */
static int sd_get_state(void *ctx)
{
    (void)ctx;
    if (hsd.State != HAL_SD_STATE_READY) {
        /* RESET: SDIO never initialised (no card at boot) or de-initialised —
         * a CMD13 on a clock-gated peripheral from the OTG_FS ISR would spin
         * the whole command timeout with the tick frozen. BUSY: an init or
         * transfer is in progress (e.g. MSC_Poll's card_init in BrendonTask);
         * a CMD13 from the ISR would corrupt it. Either way: not ready yet. */
        return (int)MSC_CARD_NOT_READY;
    }
    switch (HAL_SD_GetCardState(&hsd)) {
        case HAL_SD_CARD_TRANSFER:    return (int)MSC_CARD_READY;
        case HAL_SD_CARD_SENDING:
        case HAL_SD_CARD_RECEIVING:
        case HAL_SD_CARD_PROGRAMMING: return (int)MSC_CARD_BUSY;
        default:                      return (int)MSC_CARD_NOT_READY;
    }
}

static int sd_card_init(void *ctx)
{
    (void)ctx;
    (void)HAL_SD_DeInit(&hsd);
    return (HAL_SD_Init(&hsd) == HAL_OK) ? 0 : -1;
}

static int sd_config_wide_bus(void *ctx)
{
    (void)ctx;
    /* BSP_SD_Init (Jack's mount) test-reads a sector over the 4-bit bus; if
     * that failed on this power cycle (breakout without D1-D3) the card must
     * stay in 1-bit mode for the host too — MSC_Poll treats -1 as "keep the
     * reliable 1-bit mode", not as an error. */
    if (SD_Bus4BitStatus() == 2U) return -1;
    /* HAL_SD_ConfigWideBusOperation re-programs SDIO from hsd.Init (transfer
     * clock = CubeMX ClockDiv, flow control off) with the 4-bit bus, so there
     * is nothing to pre-set here: any manual SDIO_Init() before this call
     * (the old "24 MHz bump") was simply overwritten by it. */
    return (HAL_SD_ConfigWideBusOperation(&hsd, SDIO_BUS_WIDE_4B) == HAL_OK) ? 0 : -1;
}

/* These run inside the OTG_FS interrupt, where HAL_GetTick() does not advance
 * (TIM5 tick is a lower-priority interrupt), so SD_BLOCK_TIMEOUT_MS never
 * expires there. Three things bound a pulled card: no transfer is started
 * when SD_DETECT reads high (active-low switch: 0 V = card inserted, measured
 * 24 Sep 2026), the command phase of a missing card fails at once (no
 * response within 64 SDIO clocks), and the SDIO hardware data timeout is set
 * to ~1 s (SDMMC_DATATIMEOUT in the root CMakeLists.txt) so a card that
 * vanishes mid-transfer raises DTIMEOUT instead of the HAL default of several
 * minutes. */
static int sd_card_absent(void)
{
    return (HAL_GPIO_ReadPin(SD_DETECT_GPIO_Port, SD_DETECT_Pin) == GPIO_PIN_SET) ? 1 : 0;
}

/* TEAM CODE (Brendon, approved 2 Nov 2026): no interrupt during the polled FIFO transfer.
 * With SDIO flow control off, a priority-5 interrupt (I2S3 TX DMA every 4 ms,
 * SDIO, SDIO DMA) pausing this loop lets the FIFO under/overrun and the block
 * fails; macOS drops a failed cached write silently, so copied files came out
 * damaged. One call is one 512-byte block (MSC_MEDIA_PACKET), ~150-200 us
 * masked; the DTIMEOUT above still bounds it. msc_wait_idle runs unmasked. */
static int sd_read_blocks(void *ctx, uint8_t *buf, uint32_t blk_addr, uint16_t blk_len)
{
    (void)ctx;
    if (sd_card_absent()) return -1;
    const uint32_t primask = __get_PRIMASK();
    __disable_irq();
    const HAL_StatusTypeDef st = HAL_SD_ReadBlocks(&hsd, buf, blk_addr, blk_len, SD_BLOCK_TIMEOUT_MS);
    __set_PRIMASK(primask);
    return (st == HAL_OK) ? 0 : -1;
}

static int sd_write_blocks(void *ctx, const uint8_t *buf, uint32_t blk_addr, uint16_t blk_len)
{
    (void)ctx;
    if (sd_card_absent()) return -1;
    const uint32_t primask = __get_PRIMASK();
    __disable_irq();
    const HAL_StatusTypeDef st = HAL_SD_WriteBlocks(&hsd, (uint8_t *)buf, blk_addr, blk_len, SD_BLOCK_TIMEOUT_MS);
    __set_PRIMASK(primask);
    return (st == HAL_OK) ? 0 : -1;
}

static int sd_get_capacity(void *ctx, uint32_t *block_num, uint16_t *block_size)
{
    (void)ctx;
    HAL_SD_CardInfoTypeDef info;
    if (HAL_SD_GetCardInfo(&hsd, &info) != HAL_OK) return -1;
    *block_num  = info.LogBlockNbr;
    *block_size = (uint16_t)info.LogBlockSize;
    return 0;
}

static const MSC_SdOps s_msc_ops = {
    .get_state       = sd_get_state,
    .card_init       = sd_card_init,
    .config_wide_bus = sd_config_wide_bus,
    .read_blocks     = sd_read_blocks,
    .write_blocks    = sd_write_blocks,
    .get_capacity    = sd_get_capacity,
    .ctx             = NULL,
};

/* ================================ init =================================== */
void BrendonPorts_Init(I2C_HandleTypeDef *hi2c)
{
    s_hi2c = hi2c;
    /* Fallback geometry keeps USB enumeration alive before the card is up
     * (0x10000 blocks of 512 B = 32 MB, the CubeMX template's numbers; the
     * PC reads the real size once the card is ready). */
    (void)MSC_Init(&s_msc_store, &s_msc_ops, 0x10000U, 0x200U);
}

const BQ_Bus       *BrendonPorts_BqBus(void)       { return &s_bq_bus; }
const Charger_Pins *BrendonPorts_ChargerPins(void) { return &s_charger_pins; }
MSC_Store          *BrendonPorts_MscStore(void)    { return &s_msc_store; }
